import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M7 4a1 1 0 0 1 2 0v2a1 1 0 0 1-2 0zm3 3h2a1 1 0 0 1 0 2h-2a1 1 0 0 1 0-2M4 7h2a1 1 0 0 1 0 2H4a1 1 0 0 1 0-2m4 2a1 1 0 0 1 1 1v2a1 1 0 0 1-2 0v-2a1 1 0 0 1 1-1m8-1A8 8 0 1 1 0 8a8 8 0 0 1 16 0m-2 0A6 6 0 1 0 2 8a6 6 0 0 0 12 0"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M9 5a1 1 0 0 1 2 0v3a1 1 0 0 1-2 0zm3 4h3a1 1 0 1 1 0 2h-3a1 1 0 0 1 0-2m-8 1a1 1 0 0 1 1-1h3a1 1 0 0 1 0 2H5a1 1 0 0 1-1-1m6 1a1 1 0 0 1 1 1v3a1 1 0 0 1-2 0v-3a1 1 0 0 1 1-1m0 9C4.477 20 0 15.523 0 10S4.477 0 10 0s10 4.477 10 10-4.477 10-10 10m0-2a8 8 0 1 0 0-16.001A8 8 0 0 0 10 18"] as readonly string[];

export const TargetIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="target" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
TargetIcon.displayName = `Blueprint6.Icon.TargetIcon`;

/**
 * @deprecated Use {@link TargetIcon} instead.
 */
export const Target: typeof TargetIcon = TargetIcon;

export default TargetIcon;
